// Render one notification as plain Telegram text.
//
// No parse_mode. Markdown and HTML both need escaping, and the text here
// contains company names, error messages and URLs written by other systems. A
// missed escape either breaks the send or silently drops part of the message,
// and a dropped line in an alert is worse than an unstyled one.

const TELEGRAM_LIMIT = 4096;
const MARGIN = 96; // room for the header and the truncation marker

function ago(ts) {
  if (!ts) return '';
  const minutes = Math.max(0, Math.round((Date.now() - new Date(ts).getTime()) / 60000));
  if (minutes < 60) return minutes + 'm';
  if (minutes < 1440) return Math.round(minutes / 60) + 'h';
  return Math.round(minutes / 1440) + 'd';
}

return $input.all().map((item) => {
  const n = item.json ?? {};
  const head = [];

  head.push(String(n.title ?? '(no title)'));

  // docs/telegram.md wants "what failed, how many times, when it started" on a
  // deduplicated alert. occurrences = 1 means it fired once; saying so would be
  // noise, so the line only appears when it adds something.
  if (Number(n.occurrences) > 1) {
    head.push('(' + n.occurrences + ' times, first ' + ago(n.first_seen_at) + ' ago)');
  }
  if (n.company_name) {
    head.push(n.company_name + (n.company_domain ? ' (' + n.company_domain + ')' : ''));
  }

  const header = head.join('\n');
  let body = String(n.body ?? '');
  const room = TELEGRAM_LIMIT - MARGIN - header.length;
  let truncated = false;
  if (body.length > room) {
    body = body.slice(0, Math.max(0, room));
    truncated = true;
  }

  const text = header + '\n\n' + body + (truncated ? '\n\n[truncated]' : '');

  return {
    json: {
      notification_id: n.notification_id,
      dedup_key: n.dedup_key,
      kind: n.kind,
      priority: n.priority,
      attempts: n.attempts,
      text,
      text_length: text.length,
      truncated,
    },
  };
});

// Decide sent or failed for each message, and make the reason safe to store.
//
// The Telegram node continues on error, so a refused send arrives as an item
// with an error rather than as a failed execution. That is deliberate: a
// failed execution would abandon the claim and leave the row at 'sending'
// until the stale timeout, and it would hand a credential-bearing error to
// WF-99.
//
// Redaction is the same rule as WF-99 with one addition: a bot token is
// <digits>:<base64ish>, and it appears verbatim in Telegram's own error URLs.
// Order matters here exactly as it does in WF-99 - the scheme rules run before
// the generic key=value rule, or the generic rule eats the word "Bearer" and
// leaves the token behind.
//
// The bot token pattern deliberately has no \\b in front of it. The string that
// actually shows up is ".../bot8123456789:AAH...", and there is no word boundary
// between the "t" of "bot" and the first digit, so an anchored pattern matches
// nothing and the whole token goes into the database. Caught by the test below,
// not by reading the code.
const MAX_ERROR = 300;

function redact(text) {
  if (typeof text !== 'string') return '';
  return text
    .replace(/\d{6,12}:[A-Za-z0-9_-]{30,}/g, '***bot-token***')
    .replace(/\b([a-z][a-z0-9+.-]*):\/\/([^:\s/@]+):([^@\s]+)@/gi, '$1://$2:***@')
    .replace(/\beyJ[A-Za-z0-9._-]{16,}/g, '***jwt***')
    .replace(/\b(Bearer|Basic|Token)\s+[A-Za-z0-9._~+/=-]{6,}/gi, '$1 ***')
    .replace(
      /\b(password|passwd|pwd|secret|token|api[_-]?key|authorization)\b(\s*[:=]\s*)(?:(?:Bearer|Basic|Token)\s+)?("?)[^\s,;"')]+\3/gi,
      '$1$2***',
    );
}

function clip(text) {
  return text.length > MAX_ERROR ? text.slice(0, MAX_ERROR) + ' ... [truncated]' : text;
}

// The Telegram node keeps only error.message when it continues on fail, and
// throws away the description that says what was actually wrong: a 400 that
// really read "Bad Request: chat not found" arrives here as "Bad request -
// please check your parameters", which tells the reader nothing.
//
// The original message is never altered. A hint is appended to it, because
// these three cover essentially every Telegram failure and the first one is
// the setup mistake everybody makes.
const HINTS = [
  [/bad request/i,
   'Likely a wrong TELEGRAM_CHAT_ID, or a recipient who has never pressed Start on the bot - a bot cannot open a conversation.'],
  [/unauthorized|forbidden|\b401\b|\b403\b/i,
   'Telegram rejected the token. Check the Telegram credential in n8n.'],
  [/too many requests|\b429\b/i,
   'Rate limited by Telegram. The retry backoff will pick this up.'],
];

function withHint(text) {
  for (const [pattern, hint] of HINTS) {
    if (pattern.test(text)) return text + ' | ' + hint;
  }
  return text;
}

// The Telegram node emits one output item per input item, so the notification
// each result belongs to is read back from Format Message by index rather than
// from the response, which does not carry it.
const sent = $input.all();
const queued = $('Format Message').all();

return sent.map((item, i) => {
  const source = queued[i]?.json ?? {};
  const res = item.json ?? {};

  // The error is on the ITEM, not inside item.json. With continueOnFail the
  // Telegram node pushes `{ json: {}, error: error.message }`, so a workflow
  // that only reads item.json.error sees an empty object and has to guess.
  // That cost a real diagnosis: Telegram answered "Bad Request: chat not
  // found" - the bot had never been started by the recipient - and the
  // database recorded "no evidence the message was sent" instead.
  // Both places are read, because other nodes put it in json.
  const errorSource = res.error ?? item.error ?? null;
  const rawError = errorSource
    ? (typeof errorSource === 'string' ? errorSource : (errorSource.message ?? JSON.stringify(errorSource)))
    : null;

  // A successful sendMessage returns the message it created. Anything without
  // a message_id is treated as a failure, including an empty response: the
  // point of this workflow is knowing whether the human was actually told.
  const messageId = res.message_id ?? res.result?.message_id ?? null;
  const delivered = rawError === null && messageId !== null;

  return {
    json: {
      notification_id: source.notification_id,
      dedup_key: source.dedup_key,
      delivered,
      telegram_message_id: messageId === null ? '' : String(messageId),
      // When the node cannot start at all - a missing or wrong credential is the
      // case seen in practice - n8n emits an empty item with no error on it, so
      // there is nothing to quote. Naming the likely cause is the difference
      // between this line being actionable and it sending the reader to look at
      // Telegram's status page.
      error: delivered
        ? ''
        : clip(withHint(redact(rawError ??
            'Telegram returned no message id, so there is no evidence the message was sent. ' +
            'The usual cause is a missing or wrong Telegram credential on the Send Telegram node.'))),
    },
  };
});
